-- Fiche Le passé composé (CM1) - conjugaison, notion 'passe_compose'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'conjugaison', 'Le passé composé', $fiche$
[titre]Un temps en deux mots[/titre]
Le passé composé raconte une action [b]terminée[/b]. Il a deux parties :
[cadre]tu [b]as[/b] [b]fermé[/b]
auxiliaire avoir au présent + participe passé[/cadre]
[page]
[titre]L'auxiliaire avoir[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]avoir + participe[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]j'ai chanté[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]as chanté[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]a chanté[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]avons chanté[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]avez chanté[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]ont chanté[/font_size][/center][/cell][/table]
[cadre=astuce]Avec avoir, le participe ne s'accorde pas avec le sujet : elles ont chant[b]é[/b].[/cadre]
[page]
[titre]Les participes réguliers[/titre]
[table=2][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]verbes en -er → [b][color=#C62828]é[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]chanter → chant[b][color=#C62828]é[/color][/b], fermer → ferm[b][color=#C62828]é[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=19]verbes comme finir → [b][color=#C62828]i[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=19]finir → fin[b][color=#C62828]i[/color][/b], choisir → chois[b][color=#C62828]i[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]beaucoup de verbes en -re → [b][color=#C62828]u[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]attendre → attend[b][color=#C62828]u[/color][/b], perdre → perd[b][color=#C62828]u[/color][/b][/font_size][/center][/cell][/table]
